package cn.mop.api;
import cn.mop.domain.*;import cn.mop.domain.configuration.RuntimeConfigurationRepository;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.mock.web.MockHttpServletRequest;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class RuntimeConfigurationReadAuthorizationTest {
 static final String A="10000000-0000-4000-8000-000000000001",T="20000000-0000-4000-8000-000000000001",KEY="monitor.page_refresh_sec";
 PlatformRepository platform;RuntimeConfigurationRepository repository;RuntimeConfigurationCatalog catalog;RuntimeConfigurationController controller;ObjectMapper mapper=new ObjectMapper();
 @BeforeEach void setup(){platform=mock(PlatformRepository.class);repository=mock(RuntimeConfigurationRepository.class);catalog=mock(RuntimeConfigurationCatalog.class);when(platform.membership(A,T)).thenReturn(Optional.of(new Membership(A,T,"padmin",7,true)));when(catalog.hash(KEY)).thenReturn("a".repeat(64));when(catalog.entry(KEY)).thenReturn(Map.of());when(catalog.definitions()).thenReturn(List.of());when(repository.read(any(),eq(KEY))).thenReturn(Map.of("status","UNCONFIGURED"));when(repository.history(any(),eq(KEY),anyLong())).thenReturn(List.of());controller=new RuntimeConfigurationController(platform,repository,catalog,mapper);}
 MockHttpServletRequest request(){var r=new MockHttpServletRequest();r.setUserPrincipal(()->A);r.getSession().setAttribute("mop.tenant_id",T);return r;}
 Object read(String mode,MockHttpServletRequest r){return switch(mode){case "catalog"->controller.catalog(r);case "current"->controller.current(KEY,r);case "history"->controller.history(KEY,r);default->controller.validate(KEY,mapper.createObjectNode().put("value",30),r);};}
 @ParameterizedTest @ValueSource(strings={"catalog","current","history","validate"}) void revocationDuringReadOrPureValidationPreventsReturn(String mode){Runnable revoke=()->when(platform.membership(A,T)).thenReturn(Optional.empty());when(catalog.definitions()).thenAnswer(c->{revoke.run();return List.of();});when(repository.read(any(),eq(KEY))).thenAnswer(c->{revoke.run();return Map.of("status","UNCONFIGURED");});when(repository.history(any(),eq(KEY),anyLong())).thenAnswer(c->{revoke.run();return List.of();});doAnswer(c->{revoke.run();return null;}).when(catalog).validate(any(),any());assertEquals(401,assertThrows(DomainException.class,()->read(mode,request())).status);}
 @ParameterizedTest @ValueSource(strings={"tenant","principal","version"}) void changedContextDuringCurrentReadPreventsReturn(String kind){var r=request();when(repository.read(any(),eq(KEY))).thenAnswer(c->{if(kind.equals("tenant"))r.getSession().setAttribute("mop.tenant_id",UUID.randomUUID().toString());else if(kind.equals("principal"))r.setUserPrincipal(()->UUID.randomUUID().toString());else when(platform.membership(A,T)).thenReturn(Optional.of(new Membership(A,T,"padmin",8,true)));return Map.of("status","UNCONFIGURED");});assertEquals(401,assertThrows(DomainException.class,()->controller.current(KEY,r)).status);}
 @Test void malformedSessionScopeDoesNotBecomeAnInternalServerError(){var r=request();r.getSession().setAttribute("mop.tenant_id",42);assertEquals(401,assertThrows(DomainException.class,()->controller.current(KEY,r)).status);verifyNoInteractions(repository);}
 @Test void successfulReadRechecksWithoutAnyPublication(){controller.current(KEY,request());verify(platform,times(2)).membership(A,T);verify(repository,never()).publish(any(),any(),any(),any());}
}
